import sys

def main():
    args = sys.argv[1:]
    if not args:
        print("sayı yok")
        return
    try:
        numbers = list(map(float, args))
        average = sum(numbers) / len(numbers)
        print("{:.2f}".format(average))
    except ValueError:
        print("Geçersiz sayılar")

if __name__ == "__main__":
    main()
